// ─────────────────────────────────────────────────────────────────────────────
// KASHMIR ECOWATCH (KEW) — AUTHORITATIVE MASTER LAKE REGISTRY & TROPHIC ATLAS
// Single Source of Truth reconciling:
//   1. DEERS (2012) Directory of Lakes & Waterbodies of J&K State (415/415 Kashmir + 45 1967→2009 Present Status)
//   2. University of Kashmir Zenodo GIS Inventory (Rashid & Kashani 2025, DOI: 10.5281/zenodo.15051825, 155/155 polygons)
//   3. CAG of India Report No. 4 of 2025 (330 historical Kashmir baseline + 13 named Kashmir audit/dried-up lakes + queue)
//   4. Ministry of Jal Shakti First Census of Water Bodies (37 J&K lakes separated from 9,728 non-lake waterbodies)
//   5. Published Peer-Reviewed Limnological Literature & Individual Carlson (1977) TSI Calculations
//   6. Existing KEW Lake Directory (62 slugs preserved 100% without regression)
// AUTO-GENERATED DETERMINISTICALLY — DO NOT HARDCODE COUNTERS IN CONSUMER PAGES.
// ─────────────────────────────────────────────────────────────────────────────

export type MasterRegionalScope =
  | 'Kashmir Division'
  | 'Jammu Division'
  | 'Ladakh'
  | 'Azad Jammu and Kashmir'
  | 'Gilgit-Baltistan';

export type MasterTrophicStatus =
  | 'Oligotrophic'
  | 'Mesotrophic'
  | 'Eutrophic'
  | 'Hypereutrophic'
  | 'Insufficient Evidence';

export type MasterDataClassification =
  | 'Inventory Only'
  | 'Satellite-Screened'
  | 'Historical Limnological Observations'
  | 'Scientifically Assessed';

export interface CarlsonTsiRecord {
  secchiDepthM: number | null;
  chlorophyllAUgL: number | null;
  totalPhosphorusUgL: number | null;
  totalNitrogenUgL: number | null;
  dissolvedOxygenMgL: number | null;
  pH: number | null;
  conductivityUsCm: number | null;
  tsiSecchi: number | null;
  tsiChlorophyllA: number | null;
  tsiTotalPhosphorus: number | null;
  observationPeriod: string | null;
  methodologicalNote: string;
}

export interface GlacialLakeHazardSummary {
  susceptibilityClass: string;
  perimeterM: number;
  area1992Ha: number;
  area2024Ha: number;
  growthPercent1992To2024: number;
  sourceDoi: string;
  assessmentDate: string;
}

export interface MasterLakeRecord {
  kewLakeId: string;
  slug: string;
  officialName: string;
  localOrAlternativeNames: string[];
  isNamed: boolean;
  regionalScope: MasterRegionalScope;
  district: string;
  parentDistrict1967: string;
  districtAssignmentBasis: string;
  watershed: string;
  coordinates: { lat: number; lng: number };
  coordinatePrecision: string;
  polygonRingWgs84: Array<[number, number]> | null;
  elevationM: number;
  waterBodyType: string;
  ecologicalSetting: 'Urban' | 'Rural / Floodplain' | 'Montane / Forest' | 'Subalpine' | 'Alpine';
  hydrologicalOrigin: string;
  persistence: string;
  historicalAreaHa: number | null;
  historicalEpoch: string | null;
  area2009DeersHa: number | null;
  openWater2009Ha: number | null;
  marshy2009Ha: number | null;
  latestVerifiedAreaHa: number | null;
  latestAreaEpoch: string;
  areaDefinition: string;
  areaChangePercent: number | null;
  areaChangeClass: string;
  maxDepthM: number | null;
  meanDepthM: number | null;
  trophicStatus: MasterTrophicStatus;
  historicalTrophicStatus: string | null;
  trophicConfidence: string;
  dataClassification: MasterDataClassification;
  carlsonTsi: CarlsonTsiRecord;
  glofSusceptibility: GlacialLakeHazardSummary | null;
  opticalBloomScreeningEligible: boolean;
  environmentalPressures: string[];
  controllingAuthority: string;
  conservationPriority: string;
  reconciliationStatus: string;
  sourceRecordIds: string[];
  sourceInventoryTags: string[];
  citations: string[];
  legacyKewSlug: string | null;
}

