const BY_SLUG = new Map<string, MasterLakeRecord>();
const BY_ID = new Map<string, MasterLakeRecord>();
for (const rec of MASTER_LAKE_REGISTRY) {
  BY_SLUG.set(rec.slug, rec);
  BY_ID.set(rec.kewLakeId, rec);
}

export function getMasterLakeBySlugOrId(slugOrId: string): MasterLakeRecord | undefined {
  return BY_SLUG.get(slugOrId) || BY_ID.get(slugOrId.toUpperCase());
}

export function getKashmirDivisionMasterLakes(): MasterLakeRecord[] {
  return MASTER_LAKE_REGISTRY.filter((r) => r.regionalScope === 'Kashmir Division');
}

export function getExtendedWesternHimalayanLakes(): MasterLakeRecord[] {
  return MASTER_LAKE_REGISTRY.filter((r) => r.regionalScope !== 'Kashmir Division');
}
